# AIDA shell helpers — generated by `aida dev shell-init --install`.
# Re-run that command to regenerate this file (e.g. after upgrading aida).

# AIDA shell wrapper.
#
# Most `aida` subcommands run as plain commands. The few that need to
# modify the calling shell (set env vars, prepend PATH, change PS1) get
# automatically eval'd so they take effect here, not in the subprocess.
#
# Bypass the wrapper with `command aida ...` if you need raw stdout.

# trace:TASK-667 — signal the wrapper's presence so the binary tailors its
# auto-eval hints. When this is set, the `aida()` function below auto-evals
# the shell-modifying subcommands, so the binary prints the BARE form
# (`aida role enter <role>`); printing `eval "$(...)"` would double-eval and
# lose the effect. The value lists the auto-evaled verb groups for any future
# wrapper-aware decisions.
#
# The trailing `eval-block` capability says this wrapper understands the
# DEDICATED EVAL CHANNEL below: shell code arrives inside a marker-delimited
# block, so ordinary stdout is never an eval candidate. A binary that does not
# see this token keeps emitting the legacy bare payload, so upgrading the binary
# under an older wrapper changes nothing. (trace:TASK-1171)
#
# `init-cd-file` says the `init` arm below reads its `cd` block from a private
# SIDE-CHANNEL FILE (handed to the binary in AIDA_INIT_CD_FILE) rather than by
# capturing stdout. The older `init-cd` token meant "slice the block out of
# captured stdout"; this wrapper deliberately does not advertise it, so a
# binary that knows only that token prints a plain copy-paste `cd` hint here
# instead of markers nobody is reading.
export AIDA_SHELL_WRAPPER='role,session,dev,worktree,worktree-exit,worktree-stale,eval-block,init-cd-file'

aida() {
    # trace:BUG-1811 | ai:antigravity
    # Suppress set -x trace for wrapper internals
    local - 2>/dev/null || true
    set +x 2>/dev/null
    # Take the first two positional words verbatim — that's enough to
    # disambiguate every eval-required subcommand we have.
    local _aida_cmd="${1:-} ${2:-}"
    case "$_aida_cmd" in
        "dev activate"|"dev deactivate"|"role enter"|"role end"|"role add"|"session start"|"session end"|"worktree enter"|"worktree exit")
            # These subcommands mutate the CALLING shell, so their shell code
            # has to be eval'd here rather than run in the subprocess. Human
            # messages (status, prompts) go to stderr, which passes straight
            # through; stdin still reaches the binary for prompts.
            #
            # DEDICATED CHANNEL (trace:TASK-1171). The binary wraps its shell
            # payload in `#aida:eval:begin` / `#aida:eval:end` markers. We slice
            # that block out and eval ONLY it — anything else on stdout is prose
            # and gets printed. That makes it structurally impossible for a
            # subcommand's human output to be eval'd, which is the class of bug
            # that turned a failed `session end` into three `command not found`
            # lines. Both markers are shell comments, so an older wrapper (or a
            # hand-rolled `eval "$(aida …)"`) that evals the lot is inert.
            #
            # trace:BUG-1806 | ai:codex
            # Failed output is diagnostic data, including any apparent markers.
            # Keep a sentinel through capture to preserve trailing newlines.
            # Old binaries without markers are display-only: never guess that
            # unmarked stdout is shell code. Validate the entire block before
            # eval, requiring exactly one pair of standalone marker lines.
            local _aida_out _aida_rc _aida_pre='' _aida_post='' _aida_eval=''
            local _aida_line _aida_state=0 _aida_valid=1
            local _aida_b='#aida:eval:begin'
            local _aida_e='#aida:eval:end'
            local _aida_nl='
'
            if _aida_out=$(command aida "$@"; _aida_rc=$?; printf '.'; exit "$_aida_rc"); then
                _aida_rc=0
            else
                _aida_rc=$?
            fi
            _aida_out=${_aida_out%.}
            if [ "$_aida_rc" -ne 0 ]; then
                printf '%s' "$_aida_out" >&2
                return "$_aida_rc"
            fi
            while IFS= read -r _aida_line; do
                case "$_aida_line" in
                    "$_aida_b")
                        [ "$_aida_state" -eq 0 ] || _aida_valid=0
                        _aida_state=1 ;;
                    "$_aida_e")
                        [ "$_aida_state" -eq 1 ] || _aida_valid=0
                        _aida_state=2 ;;
                    *)
                        case "$_aida_state" in
                            0) _aida_pre="$_aida_pre$_aida_line$_aida_nl" ;;
                            1) _aida_eval="$_aida_eval$_aida_line$_aida_nl" ;;
                            2) _aida_post="$_aida_post$_aida_line$_aida_nl" ;;
                        esac ;;
                esac
            done <<AIDA_WRAPPER_OUTPUT
${_aida_out%"$_aida_nl"}
AIDA_WRAPPER_OUTPUT
            if [ "$_aida_valid" -eq 1 ] && [ "$_aida_state" -eq 2 ]; then
                printf '%s' "$_aida_pre"
                [ -n "$_aida_eval" ] && eval "$_aida_eval"
                printf '%s' "$_aida_post"
            else
                printf '%s' "$_aida_out"
            fi
            return 0
            ;;
        "init"|"init "*)
            # STORY-780: `aida init <DIR>` finishes by handing this shell a
            # `cd` into the new project. The block travels on a SIDE CHANNEL,
            # not stdout: we hand the binary a private file in
            # AIDA_INIT_CD_FILE and it writes the same marker-delimited block
            # there. The child's stdout, stderr and stdin stay attached to the
            # terminal, so an interactive init renders human output and shows
            # its prompts live. Capturing stdout here used to make the child
            # see a pipe (auto-selecting the agent format) and buffered every
            # prompt invisibly until exit, so a prompt waiting on stdin looked
            # like a hang.
            #
            # Nothing on stdout is EVER an eval candidate in this arm, and
            # there is no bare-payload fallback: only a file holding exactly
            # one marker pair and nothing else is eval'd. A failing init, an
            # empty file (older binary, in-place init) or a malformed file all
            # leave the shell where it was. The env assignment is a per-command
            # prefix, so it never leaks into this shell.
            local _aida_cd_file _aida_rc _aida_eval=''
            local _aida_line _aida_state=0 _aida_valid=1
            local _aida_b='#aida:eval:begin'
            local _aida_e='#aida:eval:end'
            local _aida_nl='
'
            _aida_cd_file=$(mktemp -t aida-init-cd.XXXXXX 2>/dev/null) || _aida_cd_file=''
            if [ -z "$_aida_cd_file" ]; then
                # No private file available: plain pass-through; the binary
                # prints the copy-paste `cd` hint.
                command aida "$@"
                return $?
            fi
            AIDA_INIT_CD_FILE="$_aida_cd_file" command aida "$@"
            _aida_rc=$?
            if [ "$_aida_rc" -ne 0 ] || ! [ -s "$_aida_cd_file" ]; then
                rm -f "$_aida_cd_file"
                return "$_aida_rc"
            fi
            while IFS= read -r _aida_line; do
                case "$_aida_line" in
                    "$_aida_b")
                        [ "$_aida_state" -eq 0 ] || _aida_valid=0
                        _aida_state=1 ;;
                    "$_aida_e")
                        [ "$_aida_state" -eq 1 ] || _aida_valid=0
                        _aida_state=2 ;;
                    *)
                        case "$_aida_state" in
                            1) _aida_eval="$_aida_eval$_aida_line$_aida_nl" ;;
                            *) _aida_valid=0 ;;
                        esac ;;
                esac
            done < "$_aida_cd_file"
            rm -f "$_aida_cd_file"
            if [ "$_aida_valid" -eq 1 ] && [ "$_aida_state" -eq 2 ] && [ -n "$_aida_eval" ]; then
                eval "$_aida_eval"
            fi
            return 0
            ;;
        "tui"|"tui "*)
            # STORY-681: `aida tui` is now self-sufficient — it dispatches
            # the launcher's chosen command IN-PROCESS and re-enters in a
            # loop, with no fd-3 pipe and no shell wrapper. So this case just
            # passes through. (BUG-612 used to route `aida tui` through the
            # `aida-tui` function to set up fd 3; that detour is no longer
            # needed. The `aida-tui` function below stays as an opt-in
            # power-user/legacy hook over the STORY-244 fd-3 protocol.)
            command aida "$@"
            ;;
        *)
            command aida "$@"
            ;;
    esac
}

_aida_dev_prompt_marker() {
    [ -n "${PS1+x}" ] || return 0
    [ -n "${AIDA_DEV_ACTIVE+x}" ] || return 0
    [ -n "${AIDA_DEV_PROFILE:-}" ] || return 0

    local _aida_marker
    _aida_marker="$(command aida dev ps1 2>/dev/null || true)"

    while case "$PS1" in *'(aida-'*') '*) true;; *) false;; esac; do
        _aida_old_ps1="$PS1"
        _aida_after="${PS1#*'(aida-'}"
        _aida_tag="${_aida_after%%') '*}"
        PS1="${PS1//'(aida-'$_aida_tag') '/}"
        [ "$PS1" = "$_aida_old_ps1" ] && break
    done
    unset _aida_old_ps1 _aida_after _aida_tag

    export AIDA_DEV_PS1_PREFIX="(aida-${AIDA_DEV_PROFILE}${_aida_marker}) "
    export PS1="$AIDA_DEV_PS1_PREFIX$PS1"
}

# Drop a DANGLING worktree marker. `aida worktree enter` records the session
# lease file backing the `(wt:...)` PS1 segment; once that lease is gone — the
# session was ended from another shell — the marker points at work that no
# longer exists, so clear it (and the session env it carried) instead of
# rendering a live-looking marker forever. Builtin-only: one file test per
# prompt, no subprocess. A shell with no recorded lease file (e.g. an
# epic-scoped worktree, or a marker spliced by an older binary) is left alone.
_aida_wt_prompt_marker() {
    [ -n "${PS1+x}" ] || return 0
    [ -n "${AIDA_WT_LEASE_FILE:-}" ] || return 0
    [ -e "$AIDA_WT_LEASE_FILE" ] && return 0

    while case "$PS1" in *'(wt:'*') '*) true;; *) false;; esac; do
        _aida_old_ps1="$PS1"
        _aida_after="${PS1#*'(wt:'}"
        _aida_tag="${_aida_after%%') '*}"
        PS1="${PS1//'(wt:'$_aida_tag') '/}"
        [ "$PS1" = "$_aida_old_ps1" ] && break
    done
    unset _aida_old_ps1 _aida_after _aida_tag
    unset AIDA_WT_PS1_PREFIX AIDA_WT_LEASE_FILE AIDA_SESSION_ID
    return 0
}

if [ -n "${ZSH_VERSION:-}" ]; then
    if ! command -v add-zsh-hook >/dev/null 2>&1; then
        autoload -Uz add-zsh-hook 2>/dev/null || true
    fi
    if command -v add-zsh-hook >/dev/null 2>&1; then
        add-zsh-hook precmd _aida_dev_prompt_marker 2>/dev/null || true
        add-zsh-hook precmd _aida_wt_prompt_marker 2>/dev/null || true
    else
        case " ${precmd_functions[*]-} " in
            *" _aida_dev_prompt_marker "*) ;;
            *) precmd_functions+=(_aida_dev_prompt_marker) ;;
        esac
        case " ${precmd_functions[*]-} " in
            *" _aida_wt_prompt_marker "*) ;;
            *) precmd_functions+=(_aida_wt_prompt_marker) ;;
        esac
    fi
else
    case ";${PROMPT_COMMAND:-};" in
        *";_aida_dev_prompt_marker;"*) ;;
        *) PROMPT_COMMAND="_aida_dev_prompt_marker${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
    esac
    case ";${PROMPT_COMMAND:-};" in
        *";_aida_wt_prompt_marker;"*) ;;
        *) PROMPT_COMMAND="_aida_wt_prompt_marker${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
    esac
fi

# STORY-244 launcher wrapper. LEGACY / power-user hook: as of STORY-681
# bare `aida tui` dispatches IN-PROCESS and re-enters on its own, so this
# function is no longer required for `aida tui` to work. It is kept for
# scripts/users that want the fd-3 wire protocol — it explicitly passes
# `--intent-fd 3` to opt into the single-shot emit mode, captures the
# intent line on fd 3, dispatches it, and re-enters. One line per run:
#
#   quit                     stop the loop
#   launch:<command>         eval <command> (typically `aida queue work …`)
#   resume:<session-id>      claude --resume <session-id>
#   shell:<command>          eval <command> (e.g. `gh pr view 42`)
#
# Pass `--once` to disable the re-entry loop (debug / scripting). All
# other args are forwarded to `aida tui --launcher`.
aida-tui() {
    local _once=0
    local -a _args=()
    while [ $# -gt 0 ]; do
        case "$1" in
            --once) _once=1; shift ;;
            *) _args+=("$1"); shift ;;
        esac
    done
    local _intent _cmd _rc
    while true; do
        # The launcher paints the real terminal (stdout/stderr) and writes
        # its single intent line to fd 3 — the redirection here moves fd 3
        # into our captured pipe and points the launcher's stdout/stderr
        # at /dev/tty so it can draw without contaminating the capture.
        _intent="$(command aida tui --launcher --intent-fd 3 "${_args[@]}" 3>&1 1>/dev/tty 2>/dev/tty)"
        case "$_intent" in
            ""|quit)
                break
                ;;
            launch:*)
                _cmd="${_intent#launch:}"
                eval "$_cmd"
                _rc=$?
                # Defensive terminal reset between Claude and the next
                # launcher entry — if the dispatched command crashed and
                # left raw mode on, this prevents the new launcher from
                # painting over garbage. trace:STORY-244 risk #3
                [ $_rc -ne 0 ] && command -v tput >/dev/null && tput reset 2>/dev/null
                ;;
            resume:*)
                claude --resume "${_intent#resume:}"
                _rc=$?
                [ $_rc -ne 0 ] && command -v tput >/dev/null && tput reset 2>/dev/null
                ;;
            shell:*)
                eval "${_intent#shell:}"
                ;;
            *)
                printf 'aida-tui: unrecognized intent line: %s\n' "$_intent" >&2
                break
                ;;
        esac
        [ $_once -eq 1 ] && break
    done
}

# AIDA autonomous-drain worker (TASK-294).
#
# Loop: read .aida/worker.cmd, act on the head directive, re-read.
#
# Directives (one per line, blank/`#` lines skipped):
#   drain                  pick queue head; run `aida queue work --auto-complete`
#   drain <args>           run `aida queue work <args> --auto-complete`; line is
#                          consumed on success (FIFO)
#   pause                  sleep 30s; line persists (worker stays paused until edited)
#   exit                   return 0
#   <anything else>        defensively treated as `pause`
#
# An overnight plan is just a heredoc:
#   printf 'drain batch:autonomy-modes --zen\ndrain batch:cleanup\nexit\n' \
#       > .aida/worker.cmd
#   aida-worker
#
# Knob: AIDA_WORKER_SPEC_TIMEOUT (default 1800s) — per-spec watchdog.
# Exit 124 from `timeout` → log "TIMED OUT" + auto-pause; other non-zero →
# log "halted" + auto-pause; "nothing to drive" output → sleep 30s only.
aida-worker() {
    local project_root cmd_file head verb rest args raw output rc
    local sleep_short=30
    project_root="$(pwd)"
    while [ ! -d "$project_root/.aida" ] && [ "$project_root" != "/" ]; do
        project_root="$(dirname "$project_root")"
    done
    if [ ! -d "$project_root/.aida" ]; then
        echo "aida-worker: no .aida/ directory found from $(pwd); refusing to run" >&2
        return 1
    fi
    cmd_file="$project_root/.aida/worker.cmd"
    echo "aida-worker: starting; directive file = $cmd_file"
    while true; do
        head=""
        if [ -f "$cmd_file" ]; then
            # Read the first non-blank, non-comment line, normalised by
            # stripping leading/trailing whitespace so an indented directive
            # like `\tdrain batch:x` matches the trimmed form that
            # `parse_directives_from_str` produces and that
            # `_aida_worker_pop_head` compares against. trace:TASK-364 | ai:claude
            head=$(awk 'NF && $1 !~ /^#/ {sub(/^[[:space:]]+/, ""); sub(/[[:space:]]+$/, ""); print; exit}' "$cmd_file" 2>/dev/null || true)
        fi
        if [ -z "$head" ]; then
            verb="drain"
            rest=""
            raw=""
        else
            verb=$(printf '%s\n' "$head" | awk '{print $1}')
            rest=$(printf '%s\n' "$head" | awk '{$1=""; sub(/^ /, ""); print}')
            raw="$head"
        fi
        case "$verb" in
            exit)
                echo "aida-worker: exit directive — stopping (rc=0)"
                return 0
                ;;
            pause)
                echo "aida-worker: pause directive — sleeping ${sleep_short}s (edit $cmd_file to resume)"
                sleep "$sleep_short"
                continue
                ;;
            drain)
                if [ -n "$rest" ]; then
                    echo "aida-worker: drain $rest"
                else
                    echo "aida-worker: drain (head pickup)"
                fi
                # Build argv. Word-splitting `$rest` is the point — directives
                # like `drain batch:x --zen` forward each word as a separate
                # arg to `aida queue work`. Note: NO `command` prefix here —
                # `timeout` invokes its child via execvp(), bypassing shell
                # function lookup entirely, and `command` is a bash builtin
                # that execvp() cannot resolve (it would fail with rc 127).
                #
                # `--kill-after=5s` is defense in depth: if the child ignores
                # the initial SIGTERM, a SIGKILL follows 5s later.
                # (Verified: GNU `timeout` reaches normal forking children
                # and exec-chains via its process-group SIGTERM. A child that
                # `setsid()`s out of the group survives — that is the residual
                # the heartbeat followup addresses.)
                # shellcheck disable=SC2086
                output=$(timeout --kill-after=5s "${AIDA_WORKER_SPEC_TIMEOUT:-1800}" aida queue work $rest --auto-complete 2>&1)
                rc=$?
                printf '%s\n' "$output"
                case "$rc" in
                    0)
                        echo "aida-worker: drain succeeded"
                        # Pop the consumed line on a scoped drain (one
                        # whose directive was a literal line in the file).
                        # A bare/absent-file `drain` has nothing to pop.
                        if [ -n "$raw" ] && [ -f "$cmd_file" ]; then
                            _aida_worker_pop_head "$cmd_file" "$raw"
                        fi
                        ;;
                    124)
                        echo "aida-worker: TIMED OUT after ${AIDA_WORKER_SPEC_TIMEOUT:-1800}s; auto-pausing"
                        printf 'pause\n' > "$cmd_file"
                        ;;
                    *)
                        if printf '%s' "$output" | grep -q 'nothing to drive'; then
                            echo "aida-worker: queue empty — sleeping ${sleep_short}s"
                            sleep "$sleep_short"
                        else
                            echo "aida-worker: halted (exit $rc); auto-pausing"
                            printf 'pause\n' > "$cmd_file"
                        fi
                        ;;
                esac
                ;;
            *)
                echo "aida-worker: unknown directive '$verb' — treating as pause (sleeping ${sleep_short}s)"
                sleep "$sleep_short"
                ;;
        esac
    done
}

# Pop the first non-blank, non-comment line whose text matches $2 from $1.
# Re-reads the file fresh so directives the user *appended* during a multi-
# minute drain survive (overwrites mid-drain are documented as racey).
_aida_worker_pop_head() {
    local file="$1"
    local target="$2"
    local tmp
    tmp=$(mktemp "${file}.XXXXXX") || return 0
    # Trim both sides of `target` and of each candidate line so an indented
    # directive matches its own trimmed form — head extraction also trims,
    # but trimming `target` here keeps the pop defensive against any caller
    # passing a raw line. trace:TASK-364 | ai:claude
    awk -v target="$target" '
        BEGIN {
            sub(/^[[:space:]]+/, "", target)
            sub(/[[:space:]]+$/, "", target)
            popped = 0
        }
        {
            if (!popped) {
                line = $0
                t = line
                sub(/^[[:space:]]+/, "", t)
                sub(/[[:space:]]+$/, "", t)
                if (length(t) == 0 || t ~ /^#/) {
                    print line
                    next
                }
                if (t == target) {
                    popped = 1
                    next
                }
            }
            print
        }
    ' "$file" > "$tmp" 2>/dev/null && mv "$tmp" "$file" || rm -f "$tmp"
}
